def policy_page(key):
 title,desc,parts=policies[key]
 sections=''.join(f'<h2>{parts[i]}</h2><p>{parts[i+1]}</p>' for i in range(0,len(parts),2))
 return f'''<section class="page-hero plain"><div class="container">{eyebrow('STORE INFORMATION')}<h1>{title}</h1><p>{desc}</p></div></section><section class="section"><div class="container policy"><span class="flag-label">DRAFT — NOT AN ACTIVE COMMERCIAL POLICY</span><p>HiTech Soloutions is preparing its final business operating terms. This page is intended to clearly disclose what is and is not configured in the website preview.</p>{sections}<h2>Contact</h2><p>Business contact details will be provided once verified. Visit <a href="contact.html" style="text-decoration:underline;color:#098b95">Contact</a> for the available inquiry tool.</p></div></section>'''

